47	using Duration = std::chrono::duration<double>;
48	
49	enum class BenchmarkLog {
50	  None, // Don't keep the internal state of the benchmark.
51	  Last, // Keep only the last batch.
52	  Full  // Keep all iterations states, useful for testing or debugging.
53	};
54	
55	// An object to configure the benchmark stopping conditions.
56	// See documentation at the beginning of the file for the overall algorithm and
57	// meaning of each field.
58	struct BenchmarkOptions {
59	  // The minimum time for which the benchmark is running.
60	  Duration min_duration = std::chrono::seconds(0);
61	  // The maximum time for which the benchmark is running.
62	  Duration max_duration = std::chrono::seconds(10);
63	  // The number of iterations in the first sample.
64	  uint32_t initial_iterations = 1;
65	  // The maximum number of iterations for any given sample.
66	  uint32_t max_iterations = 10000000;
67	  // The minimum number of samples.
68	  uint32_t min_samples = 4;
69	  // The maximum number of samples.
70	  uint32_t max_samples = 1000;
71	  // The benchmark will stop if the relative difference between the current and
72	  // the last estimation is less than epsilon. This is 1% by default.
73	  double epsilon = 0.01;
74	  // The number of iterations grows exponentially between each sample.
75	  // Must be greater or equal to 1.
76	  double scaling_factor = 1.4;
77	  BenchmarkLog log = BenchmarkLog::None;
78	};
