80	// The state of a benchmark.
81	enum class BenchmarkStatus {
82	  Running,
83	  MaxDurationReached,
84	  MaxIterationsReached,
85	  MaxSamplesReached,
86	  PrecisionReached,
87	};
88	
89	// The internal state of the benchmark, useful to debug, test or report
90	// statistics.
91	struct BenchmarkState {
92	  size_t last_sample_iterations;
93	  Duration last_batch_elapsed;
94	  BenchmarkStatus current_status;
95	  Duration current_best_guess; // The time estimation for a single run of `foo`.
96	  double change_ratio; // The change in time estimation between previous and
97	                       // current samples.
98	};
99	
100	#ifdef LIBC_BENCHMARKS_HAS_LLVM_SUPPORT
101	using BenchmarkLogType = llvm::SmallVector<BenchmarkState, 16>;
102	#else
103	#include <vector>
104	using BenchmarkLogType = std::vector<BenchmarkState>;
105	#endif
106	
107	// A lightweight result for a benchmark.
108	struct BenchmarkResult {
109	  BenchmarkStatus termination_status = BenchmarkStatus::Running;
110	  Duration best_guess = {};
111	  std::optional<BenchmarkLogType> maybe_benchmark_log;
112	};
113	
114	// Stores information about a cache in the host memory system.
115	struct CacheInfo {
116	  std::string type; //  e.g. "Instruction", "Data", "Unified".
117	  int level;        // 0 is closest to processing unit.
118	  int size;         // In bytes.
119	  int num_sharing;  // The number of processing units (Hyper-Threading Thread)
120	                    // with which this cache is shared.
121	};
122	
123	// Stores information about the host.
124	struct HostState {
125	  std::string cpu_name; // returns a string compatible with the -march option.
126	  double cpu_frequency; // in Hertz.
127	  std::vector<CacheInfo> caches;
128	
129	  static HostState get();
130	};
131	
132	namespace internal {
133	
134	struct Measurement {
135	  size_t iterations = 0;
136	  Duration elapsed = {};
137	};
138	
139	// Updates the estimation of the elapsed time for a single iteration.
140	class RefinableRuntimeEstimation {
141	  Duration total_time = {};
142	  size_t total_iterations = 0;
143	
144	public:
145	  Duration update(const Measurement &m) {
146	    assert(m.iterations > 0);
147	    // Duration is encoded as a double (see definition).
148	    // `total_time` and `m.elapsed` are of the same magnitude so we don't expect
149	    // loss of precision due to radically different scales.
150	    total_time += m.elapsed;
151	    total_iterations += m.iterations;
152	    return total_time / total_iterations;
153	  }
154	};
155	
156	// This class tracks the progression of the runtime estimation.
157	class RuntimeEstimationProgression {
158	  RefinableRuntimeEstimation rre;
159	
160	public:
161	  Duration current_estimation = {};
162	
163	  // Returns the change ratio between our best guess so far and the one from the
164	  // new measurement.
165	  double compute_improvement(const Measurement &m) {
166	    const Duration new_estimation = rre.update(m);
167	    const double ratio = fabs(((current_estimation / new_estimation) - 1.0));
168	    current_estimation = new_estimation;
169	    return ratio;
170	  }
171	};
172	
173	} // namespace internal
