175	// Measures the runtime of `foo` until conditions defined by `Options` are met.
176	//
177	// To avoid measurement's imprecisions we measure batches of `foo`.
178	// The batch size is growing by `ScalingFactor` to minimize the effect of
179	// measuring.
180	//
181	// Note: The benchmark is not responsible for serializing the executions of
182	// `foo`. It is not suitable for measuring, very small & side effect free
183	// functions, as the processor is free to execute several executions in
184	// parallel.
185	//
186	// - Options: A set of parameters controlling the stopping conditions for the
187	//     benchmark.
188	// - foo: The function under test. It takes one value and returns one value.
189	//     The input value is used to randomize the execution of `foo` as part of a
190	//     batch to mitigate the effect of the branch predictor. Signature:
191	//     `ProductType foo(ParameterProvider::value_type value);`
192	//     The output value is a product of the execution of `foo` and prevents the
193	//     compiler from optimizing out foo's body.
194	// - ParameterProvider: An object responsible for providing a range of
195	//     `Iterations` values to use as input for `foo`. The `value_type` of the
196	//     returned container has to be compatible with `foo` argument.
197	//     Must implement one of:
198	//     `Container<ParameterType> generateBatch(size_t Iterations);`
199	//     `const Container<ParameterType>& generateBatch(size_t Iterations);`
200	// - Clock: An object providing the current time. Must implement:
201	//     `std::chrono::time_point now();`
202	template <typename Function, typename ParameterProvider,
203	          typename BenchmarkClock = const std::chrono::high_resolution_clock>
204	BenchmarkResult benchmark(const BenchmarkOptions &options,
205	                          ParameterProvider &PP, Function foo,
206	                          BenchmarkClock &Clock = BenchmarkClock()) {
207	  BenchmarkResult result;
208	  internal::RuntimeEstimationProgression rep;
209	  Duration total_benchmark_duration = {};
210	  size_t iterations = std::max(options.initial_iterations, uint32_t(1));
211	  size_t samples = 0;
212	  if (options.scaling_factor < 1.0)
213	    report_fatal_error("scaling_factor should be >= 1");
214	  if (options.log != BenchmarkLog::None)
215	    result.maybe_benchmark_log.emplace();
216	  for (;;) {
217	    // Request a new Batch of size `iterations`.
218	    const auto &batch = PP.generate_batch(iterations);
219	
220	    // Measuring this Batch.
221	    const auto start_time = Clock.now();
222	    for (const auto parameter : batch) {
223	      auto production = foo(parameter);
224	      benchmark::DoNotOptimize(production);
225	    }
226	    const auto end_time = Clock.now();
227	    const Duration elapsed = end_time - start_time;
228	
229	    // Updating statistics.
230	    ++samples;
231	    total_benchmark_duration += elapsed;
232	    const double change_ratio = rep.compute_improvement({iterations, elapsed});
233	    result.best_guess = rep.current_estimation;
234	
235	    // Stopping condition.
236	    if (total_benchmark_duration >= options.min_duration &&
237	        samples >= options.min_samples && change_ratio < options.epsilon)
238	      result.termination_status = BenchmarkStatus::PrecisionReached;
239	    else if (samples >= options.max_samples)
240	      result.termination_status = BenchmarkStatus::MaxSamplesReached;
241	    else if (total_benchmark_duration >= options.max_duration)
242	      result.termination_status = BenchmarkStatus::MaxDurationReached;
243	    else if (iterations >= options.max_iterations)
244	      result.termination_status = BenchmarkStatus::MaxIterationsReached;
245	
246	    if (result.maybe_benchmark_log) {
247	      auto &benchmark_log = *result.maybe_benchmark_log;
248	      if (options.log == BenchmarkLog::Last && !benchmark_log.empty())
249	        benchmark_log.pop_back();
250	      BenchmarkState bs;
251	      bs.last_sample_iterations = iterations;
252	      bs.last_batch_elapsed = elapsed;
253	      bs.current_status = result.termination_status;
254	      bs.current_best_guess = result.best_guess;
255	      bs.change_ratio = change_ratio;
256	      benchmark_log.push_back(bs);
257	    }
258	
259	    if (result.termination_status != BenchmarkStatus::Running)
260	      return result;
261	
262	    if (options.scaling_factor > 1 &&
263	        iterations * options.scaling_factor == iterations)
264	      report_fatal_error("`iterations *= scaling_factor` is idempotent, "
265	                         "increase scaling_factor "
266	                         "or initial_iterations.");
267	
268	    iterations *= options.scaling_factor;
269	  }
270	}
271	
272	// Interprets `Array` as a circular buffer of `Size` elements.
273	template <typename T> class CircularArrayRef {
274	  llvm::ArrayRef<T> array;
275	  size_t size;
276	
277	public:
278	  using value_type = T;
279	  using reference = T &;
280	  using const_reference = const T &;
281	  using difference_type = ssize_t;
282	  using size_type = size_t;
283	
284	  class const_iterator {
285	    using iterator_category = std::input_iterator_tag;
286	    llvm::ArrayRef<T> array;
287	    size_t index;
288	    size_t offset;
289	
290	  public:
291	    explicit const_iterator(llvm::ArrayRef<T> array, size_t index = 0)
292	        : array(array), index(index), offset(index % array.size()) {}
293	    const_iterator &operator++() {
294	      ++index;
295	      ++offset;
296	      if (offset == array.size())
297	        offset = 0;
298	      return *this;
299	    }
300	    bool operator==(const_iterator other) const { return index == other.index; }
301	    bool operator!=(const_iterator other) const { return !(*this == other); }
302	    const T &operator*() const { return array[offset]; }
303	  };
304	
305	  CircularArrayRef(llvm::ArrayRef<T> array, size_t size)
306	      : array(array), size(size) {
307	    assert(array.size() > 0);
308	  }
309	
310	  const_iterator begin() const { return const_iterator(array); }
311	  const_iterator end() const { return const_iterator(array, size); }
312	};
313	
314	// A convenient helper to produce a CircularArrayRef from an ArrayRef.
315	template <typename T>
316	CircularArrayRef<T> cycle(llvm::ArrayRef<T> array, size_t size) {
317	  return {array, size};
318	}
319	
320	// Creates an std::array which storage size is constrained under `Bytes`.
321	template <typename T, size_t Bytes>
322	using ByteConstrainedArray = std::array<T, Bytes / sizeof(T)>;
323	
324	// A convenient helper to produce a CircularArrayRef from a
325	// ByteConstrainedArray.
326	template <typename T, size_t N>
327	CircularArrayRef<T> cycle(const std::array<T, N> &container, size_t size) {
328	  return {llvm::ArrayRef<T>(container.cbegin(), container.cend()), size};
329	}
330	
331	// Makes sure the binary was compiled in release mode and that frequency
332	// governor is set on performance.
333	void checkRequirements();
